import{_ as n,C as t,o,c as i,E as r,a2 as d}from"./chunks/framework.BdWD-ld-.js";const b=JSON.parse('{"title":"Before a Lesson Enters the Skill Library, Bind It to the Program That Was Tested","description":"","frontmatter":{"title":"Before a Lesson Enters the Skill Library, Bind It to the Program That Was Tested","article_type":"comparative-study","edition":"research-center","research_question":"可复用经验入库时，哪些精确程序、开发运行和建议构成接收依据？","research_question_en":"When admitting experience into a shared skill library, which program, runs and proposals should the evidence bind?","summary":"Program measurements, proposal judgments and admitted edits need separate acceptance. Two studies and eight internal function fixtures show what exact-program binding checks, while leaving per-edit semantic correspondence unverified.","sources":["https://arxiv.org/html/2611.33739v1","https://arxiv.org/html/2611.33560v1","https://raw.githubusercontent.com/lmsdss/Skeptic/bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb/skeptic/gate/promote.py"],"date":"2026-11-27","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261127-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-27-sig-20261127-002-2026-11-27-skill-evidence-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-11-27-sig-20261127-002.md","filePath":"en/engineering/2026-11-27-sig-20261127-002.md","lastUpdated":1795781635000}'),c={name:"en/engineering/2026-11-27-sig-20261127-002.md"};function l(h,e,p,u,m,g){const s=t("ArticleCover"),a=t("ArticleTableScroll");return o(),i("div",null,[r(s,{image:"/assets/covers/daily-2026-11-27-sig-20261127-002-2026-11-27-skill-evidence-cover.png",kicker:"Research",title:"Before a Lesson Enters the Skill Library, Bind It to the Program That Was Tested",summary:"Program measurements, proposal judgments and admitted edits need separate acceptance. Two studies and eight internal function fixtures show what exact-program binding checks, while leaving per-edit semantic correspondence unverified.",version:"2026-11-27",languageHref:"/zh/engineering/2026-11-27-sig-20261127-002",languageLabel:"中文"}),r(a,{language:"en"}),e[0]||(e[0]=d(`<h1 id="before-a-lesson-enters-the-skill-library-bind-it-to-the-program-that-was-tested" tabindex="-1">Before a Lesson Enters the Skill Library, Bind It to the Program That Was Tested <a class="header-anchor" href="#before-a-lesson-enters-the-skill-library-bind-it-to-the-program-that-was-tested" aria-label="Permalink to &quot;Before a Lesson Enters the Skill Library, Bind It to the Program That Was Tested&quot;">​</a></h1><p>A repair report contains a sound proposal and its source program clears the development threshold. Should the library accept the entire edit? The available research separates three judgments: the program can perform a task, a proposal deserves retention, and the edited text actually expresses that proposal. For maintainers of shared skill libraries, the useful question is whose measurements support which new text. The cases below turn that question into concrete checks.</p><h2 id="the-two-studies-accept-different-objects" tabindex="-1">The two studies accept different objects <a class="header-anchor" href="#the-two-studies-accept-different-objects" aria-label="Permalink to &quot;The two studies accept different objects&quot;">​</a></h2><p>A skill library carries strategies and experience into later tasks. Admitting a lesson therefore extends its influence beyond the attempt that produced it. Before comparing admission mechanisms, identify what each decision accepts.</p><p>RegHarness distinguishes within-run step commitment from between-run skill refinement. Its authors describe a step entering committed code after error-free execution, verifier success and an auditor’s commit proposal. Between-run refinements use default-off switches, off-state equivalence checks and leakage inspection; the authors choose which changes to enable. The library stays frozen within a trial. That is author-gated refinement, not an automatic evidence-based comparison of every lesson against its predecessor. <a href="https://arxiv.org/html/2611.33739v1" target="_blank" rel="noreferrer">Sections 3.1–3.6 and Appendices A–C</a></p><p>Skeptic sets a different contract for admitting knowledge. In its LIBERO robot-manipulation setting, a source program must succeed on at least eight of fifteen development seeds, and a fresh verifier must judge a proposed repair sound. Seeds specify development trial conditions; the score is not a guarantee across future tasks. The paper uses a separate threshold of fourteen out of twenty-five for Robosuite, a robot simulation environment. Eight out of fifteen is not a universal threshold. <a href="https://arxiv.org/html/2611.33560v1" target="_blank" rel="noreferrer">Section 3.3 and Appendices F–G</a></p><table tabindex="0"><thead><tr><th>Object being accepted</th><th>Decider and evidence</th><th>What the admitted material supports</th></tr></thead><tbody><tr><td>A RegHarness code step</td><td>Verifier and auditor assess execution and propose commitment</td><td>Author-described step conditions; replay reruns code rather than restoring an identical physical state</td></tr><tr><td>A RegHarness between-run refinement</td><td>Authors choose after switch, equivalence and leakage checks</td><td>Author-described refinement selection, rather than automatic per-proposal admission</td></tr><tr><td>A Skeptic skill lesson</td><td>A service outside editable programs checks development performance and verification</td><td>Author-described and source-observed program eligibility; correspondence of every edit still needs separate examination</td></tr></tbody></table><p>The papers have different authors and institutions and supply two independent sources for this contract comparison. They do not reproduce each other’s effectiveness. This synthesis compares decision objects, evidence and responsibility; it does not rank scores from different experiments. Each capability in the table remains attributed to its source.</p><h2 id="keep-the-score-attached-to-the-same-program" tabindex="-1">Keep the score attached to the same program <a class="header-anchor" href="#keep-the-score-attached-to-the-same-program" aria-label="Permalink to &quot;Keep the score attached to the same program&quot;">​</a></h2><p>At revision <code>bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb</code>, Skeptic’s public admission script hashes the selected <code>fix_code.py</code>, then collects finished runs whose saved program has that same hash. For each development seed it retains the result with the greatest run name and recounts coverage and passes. It does not simply trust “8/15” in the verification report. “Latest” here means the script’s run-name ordering, not a causal-order or cross-host clock guarantee. <a href="https://raw.githubusercontent.com/lmsdss/Skeptic/bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb/skeptic/gate/promote.py" target="_blank" rel="noreferrer">Run collection and eligibility functions</a></p><p>This equivalent, shortened sketch shows the program-score relationship in that fixed source. It omits report checks and is not a callable interface:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>selected_hash = hash(selected_program)</span></span>
<span class="line"><span>matching_runs = finished_runs_with_program_hash(selected_hash)</span></span>
<span class="line"><span>latest_results = greatest_run_name_for_each_development_seed(matching_runs)</span></span>
<span class="line"><span>program_eligible = every_seed_is_covered(latest_results)</span></span>
<span class="line"><span>                   and count_successes(latest_results) &gt;= 8</span></span></code></pre></div><p>For a small example, change one line of the selected program while leaving a report that says “8/15.” Reusing the old score would attach measurements to the wrong content. The script instead looks for runs of the changed program. If all saved copies contain the old version, coverage for the new one is zero. Hash binding identifies whose score this is; it does not establish program safety or proposal truth.</p><h2 id="eight-fixtures-exercise-the-admission-functions" tabindex="-1">Eight fixtures exercise the admission functions <a class="header-anchor" href="#eight-fixtures-exercise-the-admission-functions" aria-label="Permalink to &quot;Eight fixtures exercise the admission functions&quot;">​</a></h2><p>The same-date Analysis stage already executed eight internal cases. It extracted three unchanged function bodies from the pinned source—<code>sha_file</code>, <code>program_runs</code> and <code>check</code>—and let them read synthetic filesystem directories. The environment was Windows with Python 3.12.9. Fixture outcomes were preset; no robot program, model, simulator or sensor pipeline ran. This article reuses completed results rather than presenting another robot experiment. <a href="/joinwell52/assets/evidence/2026-11-27-sig-20261127-002/skill-evidence.json">Case results and provenance</a>, <a href="/joinwell52/assets/evidence/2026-11-27-sig-20261127-002/fixture-corpus.json">public synthetic fixture corpus</a></p><p>Unless a row changes it, the reference input has one matching program, all fifteen seeds covered, eight passes and one proposal judged sound.</p><table tabindex="0"><thead><tr><th>Fixture change</th><th>Actual eligibility</th><th>What the case examines</th></tr></thead><tbody><tr><td>Positive control</td><td>Eligible</td><td>The disclosed conditions can pass on this synthetic input</td></tr><tr><td>Seven rather than eight passes</td><td>Ineligible</td><td>The threshold uses recounted results</td></tr><tr><td>Only fourteen seed records</td><td>Ineligible</td><td>Eight passes do not replace complete coverage</td></tr><tr><td>Overall report refuted, one sound proposal retained</td><td>Eligible</td><td>Whole-report and individual-proposal judgments differ</td></tr><tr><td>Overall report void, one sound proposal retained</td><td>Ineligible</td><td>A void report cannot supply the required judgment</td></tr><tr><td>No sound proposal</td><td>Ineligible</td><td>A passing program does not replace proposal assessment</td></tr><tr><td>Selected program changed, old runs retained</td><td>Ineligible, zero coverage</td><td>Old measurements do not follow changed content</td></tr><tr><td>A later failing run added for a previously passing seed</td><td>Ineligible, recounted as 7/15</td><td>Selection cannot retain only an older successful result</td></tr></tbody></table><p>All eight actual outcomes matched their preset expectations. “8/8 matched” describes this function-fixture collection, not a task success rate or complete service-path coverage. A transparent text corpus retains the original archive’s 384 member files for these eight admission cases, preserving their bytes and per-file integrity information. The results file records source hashes, revision, extracted functions, inputs and outputs so the experiment record can be distinguished from our interpretation.</p><h2 id="why-a-refuted-report-can-still-carry-a-sound-proposal" tabindex="-1">Why a refuted report can still carry a sound proposal <a class="header-anchor" href="#why-a-refuted-report-can-still-carry-a-sound-proposal" aria-label="Permalink to &quot;Why a refuted report can still carry a sound proposal&quot;">​</a></h2><p>The script permits an overall verdict of <code>verified</code> or <code>refuted</code>, excludes <code>void</code>, and requires at least one proposal with disposition <code>sound</code>. This is not an explanation invented to excuse an anomalous pass. Its introductory comment explicitly says that requiring an overall verified verdict would let one defective entry sink an otherwise sound attempt, while only sound proposals may be promoted. <a href="https://raw.githubusercontent.com/lmsdss/Skeptic/bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb/skeptic/gate/promote.py" target="_blank" rel="noreferrer">Pinned source description and checks</a></p><p>The refuted-with-sound case is therefore an important positive control. Summarizing the contract as “only verified reports may enter the library” would erase its intended partial-acceptance semantics.</p><p>The next question concerns what is actually written. Does every edited passage correspond to that sound proposal? The inspected eligibility function checks attempt-level conditions. Later source processing rechecks evidence, rejects a stale library hash and lints staged content, but the admitted path does not visibly establish a semantic mapping from each edit to its sound proposal. The coordinator’s instructions carry the restriction to retain only sound proposals. This is an assurance boundary to examine, not a reproduced incident of incorrect admission. The coordinator may follow those instructions correctly. The eight fixtures did not execute the downstream library-writing process or test that correspondence.</p><p>Our interpretation for shared-library maintenance is to account separately for <strong>program eligibility, proposal judgment and edit correspondence</strong>. They can contribute to one admission decision without substituting for each other. The presence of a report is not evidence that all three hold.</p><h2 id="aim-the-next-check-at-the-admitted-text" tabindex="-1">Aim the next check at the admitted text <a class="header-anchor" href="#aim-the-next-check-at-the-admitted-text" aria-label="Permalink to &quot;Aim the next check at the admitted text&quot;">​</a></h2><p>Start with one proposed lesson and inspect four things in order: the selected program’s content hash; complete development-seed coverage and the chosen run for each seed; each proposal’s disposition and source; and the correspondence between final edits and those proposals. The first three have different levels of support in the source observations and fixtures above. The fourth is a proposed additional acceptance check, not an already verified capability.</p><p>A discriminating follow-up integration experiment would hold the passing program and sound proposal constant while changing only the staged text. One version would faithfully express the proposal; the other would mix in an unsupported conclusion. The real admission service’s handling of those versions remains untested. We do not predict whether it would reject or accept them.</p><p>The non-applicability boundaries are concrete. A conversation-ending orchestrator is not admitting reusable knowledge. Eight out of fifteen is a policy for one development setting, not a safety threshold. Matching hashes establish content identity without supplying missing observations. In a counterexample reported by Skeptic’s authors, a task with 12/15 development successes was still closed on a mistaken impossibility judgment, with no knob-angle measurement available. Program scores do not automatically repair task closure. RegHarness also reports false commits, replay aborts and governance-induced failures. We have not reproduced either full study and infer no general efficacy guarantee. <a href="https://arxiv.org/html/2611.33560v1" target="_blank" rel="noreferrer">Skeptic Appendices C, E and H</a>, <a href="https://arxiv.org/html/2611.33739v1" target="_blank" rel="noreferrer">RegHarness Sections 4.4–4.7 and appendices</a></p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>This article separates author-reported claims, source observations, internal experiments and interpretation. Author claims describe their methods and reported scope; source observations concern a pinned file; the internal fixtures exercise limited functions; per-edit acceptance is a proposed next check. Two independent author teams are not independent replications of one another, and public availability does not increase a claim’s evidentiary strength by itself.</p><ul><li>Shengming Liu et al., <em>RegHarness: Regulating What Code-as-Policy Agents Keep from Steps to Skills</em>, author preprint, November 2026, v1. <a href="https://arxiv.org/html/2611.33739v1" target="_blank" rel="noreferrer">Paper and supplement</a>. Supports the described step-commit and author-enabled refinement contracts. Implementation code and raw trial-log reproduction were not available in the admitted material.</li><li>Wenfang Sun et al., <em>Skeptic: Grounding Failure Diagnosis for Robot Skill Discovery</em>, author preprint, November 2026, v1. <a href="https://arxiv.org/html/2611.33560v1" target="_blank" rel="noreferrer">Paper and supplement</a>. Supports the reported program-performance and proposal-judgment contract and counterexamples. A fresh verifier is a separate execution role, not an independent research institution.</li><li>Skeptic project, <a href="https://raw.githubusercontent.com/lmsdss/Skeptic/bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb/skeptic/gate/promote.py" target="_blank" rel="noreferrer">admission script</a> at <code>bf0e78d2e2ce308d9d678e0bbb1196b5b3ad4ebb</code>. This belongs to the same author source as the preceding paper. The inspected code is not asserted to be the exact revision behind every paper measurement.</li><li>Research Center, internal source-function experiment, 2026-11-27: <a href="/joinwell52/assets/evidence/2026-11-27-sig-20261127-002/skill-evidence.json">eight cases, environment and mapping</a>, <a href="/joinwell52/assets/evidence/2026-11-27-sig-20261127-002/fixture-corpus.json">synthetic input corpus</a>. Supports bounded program-evidence checks, not real robot gains, proposal truth, per-edit semantic binding or full-service security.</li></ul>`,30))])}const v=n(c,[["render",l]]);export{b as __pageData,v as default};
